"""Generate a local review desk from the exact current artifacts; never approve them."""
import hashlib, html, json
from review_diagrams import markup
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def digest(data):
    return hashlib.sha256(data).hexdigest()

def prepare(root=ROOT):
    source = root/'app/src/main/assets/packs/starter.json'
    raw = source.read_bytes()
    pack = json.loads(raw)
    out = root/'release/review-kit'
    out.mkdir(parents=True, exist_ok=True)
    esc = lambda value: html.escape(str(value), quote=True)
    rows = []
    for a in sorted(pack['activities'], key=lambda a: (a['year'], a['game'], a['id'])):
        details = ''.join(f'<dt>{esc(label)}</dt><dd>{esc(value)}</dd>' for label,value in [
            ('Objective',a['objective']),('Reference',a['reference']),('Skill / prerequisites',a['skill']+' / '+', '.join(a['prerequisites'])),
            ('Type / difficulty',a['type']+' / '+str(a['difficulty'])),('Passage',a['story']),('Prompt',a['prompt']),
            ('Choices / tiles',' | '.join(a['choices'])),('Correct answer',a['answer']),('Explanation',a['explanation']),
            ('Progressive hints',' | '.join(a['hints'])),('Visual metadata',a['visual']),('Current status',a['reviewStatus'])])
        rows.append(f'<article{" hidden" if len(rows)>=12 else ""} data-id="{esc(a["id"])}" data-year="{a["year"]}"><h2>Year {a["year"]} · {esc(a["game"])} · {esc(a["id"])}</h2>{markup(a)}<dl>{details}</dl><label>Decision <select class="decision"><option value="Pending">Not reviewed</option><option value="Approved">Approve this item</option><option value="Rejected">Needs correction</option></select></label><label>Corrections / review notes <textarea class="notes" rows="2"></textarea></label></article>')
    page = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkillSprout teacher review</title><style>body{font:17px/1.5 system-ui;color:#183f32;background:#fffaf1;margin:0}main{max-width:1000px;margin:auto;padding:24px}article{background:white;border:1px solid #c8d7c8;border-radius:12px;padding:22px;margin:24px 0;break-inside:avoid}dt{font-weight:700;margin-top:8px}dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}label{display:block;margin:14px 0}input,select,textarea,button{font:inherit;padding:8px;max-width:100%;box-sizing:border-box}textarea{width:100%}.notice{padding:18px;background:#edf3e8}nav{position:sticky;top:0;background:#fffaf1;padding:12px;border-bottom:1px solid #c8d7c8}code{overflow-wrap:anywhere}@media print{nav,button,input[type=file]{display:none}article{border-radius:0}}</style><main><h1>Review the learning activities</h1><p class="notice">All items start unreviewed. Check accuracy, age/difficulty, ambiguity, distractors, hints, explanations, references, prerequisites and visual/narration behaviour in the app. Year tags are not proof of curriculum coverage. Export saves your work to a private JSON file; it does not approve a release or change the pack. Keep completed forms outside the public repository. Reloading loses unsaved decisions: export regularly, then import your saved file to resume.</p><p>Pack SHA-256: <code>PACK_HASH</code>. Activities: ITEM_COUNT.</p><label>Your name <input id="reviewer" autocomplete="off"></label><label>Relevant teaching qualification / experience <input id="qualifications" size="65" autocomplete="off"></label><label>Review date <input id="reviewedAt" type="date"></label><label>Review scope / evidence (include app/device checks and limitations) <textarea id="evidence" rows="3"></textarea></label><nav><label>Show year <select id="year"><option value="">All years</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option><option>6</option></select></label><span id="progress"></span> <p><button id="previous">Previous 12</button> <span id="pageInfo"></span> <button id="next">Next 12</button></p><button id="save">Export private review JSON</button> <label>Resume saved review <input id="load" type="file" accept="application/json"></label><p id="message" role="status"></p></nav>ROWS</main><script>
const packHash='PACK_HASH', articles=[...document.querySelectorAll('article')];
const field=id=>document.getElementById(id);
function progress(){const done=articles.filter(a=>a.querySelector('select').value!=='Pending').length;field('progress').textContent=done+' / '+articles.length+' reviewed';}
document.addEventListener('change',progress);progress();
let page=0;
function paginate(){const matches=articles.filter(a=>!field('year').value||a.dataset.year===field('year').value);const visible=new Set(matches.slice(page*12,page*12+12));articles.forEach(a=>a.hidden=!visible.has(a));field('pageInfo').textContent='Page '+(page+1)+' of '+Math.ceil(matches.length/12);field('previous').disabled=page===0;field('next').disabled=(page+1)*12>=matches.length;}
field('year').onchange=()=>{page=0;paginate();};field('previous').onclick=()=>{page--;paginate();};field('next').onclick=()=>{page++;paginate();};paginate();
field('save').onclick=()=>{
 const review={packSha256:packHash,reviewer:field('reviewer').value.trim(),qualifications:field('qualifications').value.trim(),reviewedAt:field('reviewedAt').value,evidence:field('evidence').value.trim(),activityDecisions:articles.map(a=>({id:a.dataset.id,status:a.querySelector('select').value,notes:a.querySelector('textarea').value.trim()}))};
 const all=review.activityDecisions.every(a=>a.status==='Approved');
 review.status=all&&review.reviewer&&review.qualifications&&review.reviewedAt&&review.evidence?'Approved':review.activityDecisions.some(a=>a.status==='Rejected')?'Rejected':'Draft';
 const url=URL.createObjectURL(new Blob([JSON.stringify(review,null,2)+'\n'],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='skillsprout-private-teacher-review.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);field('message').textContent='Exported '+review.status+' review. Store the file privately.';
};
field('load').onchange=async()=>{try{const f=field('load').files[0];if(!f)return;if(f.size>2000000)throw Error('File too large');const r=JSON.parse(await f.text());if(r.packSha256!==packHash)throw Error('Different content pack: review cannot be reused');const ids=new Set(articles.map(a=>a.dataset.id));if(!Array.isArray(r.activityDecisions)||r.activityDecisions.length!==ids.size||new Set(r.activityDecisions.map(a=>a.id)).size!==ids.size||r.activityDecisions.some(a=>!ids.has(a.id)||!['Pending','Approved','Rejected'].includes(a.status)||typeof a.notes!=='string'))throw Error('Incomplete or invalid decision list');for(const id of ['reviewer','qualifications','reviewedAt','evidence']){if(typeof r[id]!=='string')throw Error('Invalid reviewer fields');}for(const id of ['reviewer','qualifications','reviewedAt','evidence'])field(id).value=r[id];const map=new Map(r.activityDecisions.map(a=>[a.id,a]));for(const a of articles){a.querySelector('select').value=map.get(a.dataset.id).status;a.querySelector('textarea').value=map.get(a.dataset.id).notes;}progress();field('message').textContent='Saved decisions restored; source pack still unchanged.';}catch(e){field('message').textContent=e.message;}};
</script></html>'''
    (out/'teacher-review.html').write_text(page.replace('PACK_HASH',digest(raw)).replace('ITEM_COUNT',str(len(rows))).replace('ROWS',''.join(rows)),encoding='utf-8')
    if (out/'review-plan.json').exists() and (out/'privacy-production-draft.json').exists():
        plan=json.loads((out/'review-plan.json').read_text('utf-8'))
        privacy=json.loads((out/'privacy-production-draft.json').read_text('utf-8'))
        gates=''.join(f'<tr><td><strong>{esc(g["gate"])}</strong><br>Pending</td><td>{esc(g["action"])}</td></tr>' for g in plan['gates'])
        paragraphs=''.join(f'<p>{esc(p)}</p>' for p in privacy['proposedAmazonSections'])
        decisions=''.join(f'<li>{esc(p)}</li>' for p in privacy['unresolvedPublisherDecisions'])
        sources=''.join(f'<li><a href="{esc(url)}">{esc(label)}</a></li>' for label,url in privacy['sources'].items())
        index=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkillSprout release review desk</title><style>body{{font:18px/1.6 system-ui;color:#193f32;background:#fffaf1;margin:0}}main{{max-width:1050px;margin:auto;padding:32px}}section{{background:white;border:1px solid #c6d4c6;padding:24px;margin:24px 0;border-radius:12px}}td,th{{padding:12px;text-align:left;vertical-align:top;border-bottom:1px solid #ddd}}table{{width:100%;border-collapse:collapse}}code,pre{{overflow-wrap:anywhere;white-space:pre-wrap;font-size:15px}}a{{color:#216636}}.notice{{background:#edf3e8;padding:18px}}@media print{{section{{break-inside:avoid}}}}</style><main><h1>Finish the release reviews</h1><p class="notice">Review status: {esc(plan['reviewerIntent']['qualification'])} Backup status: {esc(plan['reviewerIntent']['signingBackup'])} Keep all current language listings for launch; their reviews remain pending. Complete one review at a time and record the actual scope and unresolved issues.</p><section><h2>1. Review the activities</h2><p><a href="teacher-review.html">Open the interactive teacher review: all {len(rows)} activities</a>. Filter by year, enter your teaching qualification/experience, review each item and save regularly with Export. Import that private JSON to resume. No item is pre-approved. Keep completed reviewer files outside the public repository.</p><p>Review the behaviour in the app as well as these written fields. In particular, check ambiguous clues, age/difficulty, repeated reading passages and limited higher-year coverage. Approving individual exercises does not establish a complete curriculum.</p></section><section><h2>2. Make and test a private publishing-key backup</h2><p>Run these commands yourself in a terminal from the project folder. Replace the example external drive path with your encrypted USB or private off-computer backup location. Enter the new passphrase only in the terminal prompt, never in chat or command arguments. Keep it in a separate password manager. The script uses scrypt and authenticated AES-256-GCM, verifies the encrypted result in memory and refuses Git destinations or overwrite.</p><pre>python tools/backup_signing.py create --backup "E:/SkillSprout-signing.skillsprout-backup"
python tools/backup_signing.py verify --backup "E:/SkillSprout-signing.skillsprout-backup"
python tools/backup_signing.py restore --backup "E:/SkillSprout-signing.skillsprout-backup" --destination "C:/Users/User/.skillsprout/signing-recovery-test"</pre><p>The restore destination must be new and outside Git. Restored files are private plaintext in that protected folder: retain them only in protected storage. A restored signing.properties retains its original keystore path; update it when recovering on another computer. Confirm the backup actually exists off this computer and that the passphrase is recoverable before approving the signing gate. The review kit does not create backups. See release/signing-backup-verification.json for the separately verified backup; exact candidate and retention approval remain pending.</p></section><section><h2>3. Review the proposed connected-app privacy notice</h2><p><strong>Draft only — not effective and not published.</strong> The live offline notice is unchanged. These proposed sections must be reconciled with it, and contradictory offline-only statements replaced, before a billing-enabled launch. <a href="privacy-production-draft.json">Complete draft and unresolved decisions (JSON)</a>.</p>{paragraphs}<h3>Publisher decisions still needed</h3><ol>{decisions}</ol><p>A privacy approval should include the completed risk assessment, final notice, provider/retention decisions, launch territories and actual store privacy answers. It must not be a statement that a draft was merely opened.</p></section><section><h2>4. Complete language, brand and device reviews</h2><p><a href="../../marketing/localized/index.html">Review all localized screenshots and listing copy</a>. Keep all requested language listings in scope. Use a competent speaker for each language; record corrections and exact file hashes. Amazon offers nine target text profiles and six target image profiles plus the preserved UK English profile. Arabic/Hindi are local packages without Amazon slots. Marketing translations do not translate learning content.</p><p>Device evidence needs the model, Fire OS/API, tested APK hash, test steps, expected/actual result and reviewer/date. Cover rotation, process death/reboot, missing offline TTS, keyboard, screen reader, large text, contrast, PIN throttling/background lock, erase/export and time controls. Billing needs physical outage/recovery, expiry, cancellation/refund and account change, followed by exact signed-candidate checks before upload. Existing sandbox successes are partial evidence. Do not perform a paid live transaction without arranging the test and its spending limit first.</p><p>Brand review covers exact and similar names, relevant classes and every launch territory, plus art/font ownership or licences. A quick web search cannot guarantee clearance.</p></section><section><h2>All remaining gates</h2><table><thead><tr><th>Gate</th><th>Action</th></tr></thead><tbody>{gates}</tbody></table><p>{esc(' '.join(plan['rules']))}</p></section><section><h2>Reference sources checked 21 October 2026</h2><ul>{sources}</ul><p><a href="manifest.json">Review source hashes</a> · <a href="review-plan.json">Machine-readable action plan</a>. Pending items remain blocked in release/evidence.json. The production build and upload are separate from public submission.</p></section></main></html>'''
        (out/'index.html').write_text(index,encoding='utf-8')
    manifest = {'packSha256':digest(raw),'activities':len(rows),'status':'Unreviewed - no approvals generated',
        'sources':{str(p.relative_to(root)).replace('\\','/'):digest(p.read_bytes()) for p in [source,root/'release/evidence.json',root/'release/amazon-localization-status.json']}}
    for name in ['review-plan.json','privacy-production-draft.json']:
        if (out/name).exists():manifest['sources']['release/review-kit/'+name]=digest((out/name).read_bytes())
    (out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
    return manifest

if __name__=='__main__':
    print(json.dumps(prepare(),indent=2))
